%[text] # Clamped beam example
%[text] Worked example of the clamped beam found in [Evaluating applied force reduced-order models: verification](https://doi.org/10.1007/s11071-026-12899-6)
%[text] ![](text:image:8888)
%[text] Make sure '`AFR_tool.prj`' is open
%%
%[text] The logging and visualisation levels determine how much is outputted to the console and as graphical representations respectively. The higher the number, the more verbose the output.
clear
set_script_wd(); %sets working directory to "...\clamped_beam" %[output:91d53801]
set_logging_level(3)
set_visualisation_level(3)
%%
%[text] ## {1}-ROM
%[text] ### Static dataset 
%[text] To create the {1}-ROM, the system (as defined in [.\\geometry\\clamped\_beam\_2d\\clamped\_beam\_2d.inp](file:.\\geometry\\clamped_beam_2d\\clamped_beam_2d.inp)), ROM limit and reduction basis needs to be specified.
%--------- System Settings ---------%
system_name = "clamped_beam_2d";
energy_limit = 0.015; %(J)
reduction_basis = 1;
%-----------------------------------%

%--------- Static Solver Settings ---------%
Static_Opts.max_parallel_jobs =  1;
%------------------------------------------%

Model = Dynamic_System(system_name,energy_limit,reduction_basis,"static_opts",Static_Opts); %[output:426c5caa] %[output:91816299] %[output:200aae47]
Static_Data = Static_Dataset(Model); %[output:7c5baff3] %[output:133f0587] %[output:8f7328dd] %[output:1acffd33]
Static_Data.save_data; %[output:667559f6]
%%
%[text] ## {1,3}-ROM
%[text] ### Static dataset 
added_mode = 3;
%[text] 
Static_Data = load_static_data("clamped_beam_2d_1");
Static_Data = Static_Data.update_model(added_mode); %[output:60a4255d] %[output:0d7c8a7c] %[output:3538fc48]
Static_Data = Static_Data.create_dataset; %[output:213dfc85]
Static_Data.save_data; %[output:1e0ef666]
%%
%[text] ## {1,3,5}-ROM
%[text] ### Static dataset 
%--------- System Settings ---------%
system_name = "clamped_beam_2d";
energy_limit = 0.015; %(J)
reduction_basis = [1,3,5];
%-----------------------------------%

%--------- Static Solver Settings ---------%
Static_Opts.max_parallel_jobs =  1;
%------------------------------------------%

%--------- Verification Solver Settings ---------%
Verification_Opts.maximum_iterations =  1;
%------------------------------------------%

Model = Dynamic_System(system_name,energy_limit,reduction_basis,"static_opts",Static_Opts); %[output:7a9d0ad3] %[output:27038722] %[output:9e3d235e]
Static_Data = Static_Dataset(Model,"verification_opts",Verification_Opts); %[output:954fdf70] %[output:30751237] %[output:3d41fc4b] %[output:008a3357]
Static_Data.save_data; %[output:0423e1c7]
%%
%[text] ### Periodic orbits
rom_name = "clamped_beam_2d_135";
Dyn_Data = initalise_dynamic_data(rom_name); %[output:4bf8de1d]
Dyn_Data = Dyn_Data.remove_solution("all");

%--------- Continuation Settings ---------%
Continuation_Opts.initial_inc = 5e-2;
Continuation_Opts.max_inc = 5e-2;
Continuation_Opts.min_inc = 1e-3;
Continuation_Opts.forward_steps = 200;
Continuation_Opts.backward_steps = 0;
Continuation_Opts.initial_discretisation_num = 20;
Continuation_Opts.max_discretisation_num = 200;
Continuation_Opts.min_discretisation_num = 20;
Continuation_Opts.collocation_degree = 6;
Continuation_Opts.parameter_range = [0,1e16] %[output:2ffcb354]
%-----------------------------------------%
Dyn_Data = Dyn_Data.add_backbone(1,"opts",Continuation_Opts); %[output:0794de6b] %[output:018d3719]
%[text] 
%[text] Can identify the last orbit by clicking on plotted points in
compare_solutions("energy","clamped_beam_2d_135",1) %[output:2afa69c8] %[output:8bb94097] %[output:0372bd21]
%[text] 
%[text] Last section
%--------- Continuation Settings ---------%
Continuation_Opts.initial_inc = 1e-2;
Continuation_Opts.max_inc = 1e-2;
Continuation_Opts.forward_steps = 1000;
Continuation_Opts.backward_steps = 1000;
%-----------------------------------------
Dyn_Data = Dyn_Data.restart_point(1,36,"po","opts",Continuation_Opts); %[output:07a18d28] %[output:72e17252] %[output:0e47c903]
%[text] Minimum frequency is 780 rad/s
%[text] 
%[text] Mid section
%--------- Continuation Settings ---------%
Continuation_Opts.initial_inc = 5e-3;
Continuation_Opts.max_inc = 5e-3;
Continuation_Opts.forward_steps = 1000;
Continuation_Opts.backward_steps = 1000;
Continuation_Opts.initial_discretisation_num = 100;
%-----------------------------------------
Dyn_Data = Dyn_Data.restart_point(1,16,"po","opts",Continuation_Opts); %[output:964bd74a] %[output:89665219]
%[text] Minimum frequency is 754 rad/s
%[text] 
%[text] First section
%--------- Continuation Settings ---------%
Continuation_Opts.initial_inc = 5e-3;
Continuation_Opts.max_inc = 5e-3;
Continuation_Opts.forward_steps = 1000;
Continuation_Opts.backward_steps = 1000;
Continuation_Opts.initial_discretisation_num = 100;
%-----------------------------------------
freq_1 = sqrt(Dyn_Data.Dynamic_Model.Model.reduced_eigenvalues(1));
Continuation_Opts.parameter_range = [freq_1,1e16]; %ensures the solution path doesn't double back on itself once 0 amplitude is reached

Dyn_Data = Dyn_Data.restart_point(1,15,"po","opts",Continuation_Opts); %[output:3c0bec90] %[output:1433fb69] %[output:7a502304]
%[text] 
%[text] Plot the parts together
compare_solutions("energy","clamped_beam_2d_135",[2,3,4]); %[output:78494c4e] %[output:2cd95e4a] %[output:411cba5d]

